using System.Collections; using UnityEngine; using UnityEngine.UI;
namespace Reflectable { public sealed class ReflectableBlockView:MonoBehaviour { [SerializeField] Text hpLabel; public int Row{get;set;} public int Column{get;set;} public int HP{get;private set;} public int MaxHP{get;private set;} public ReflectableBlockType Type{get;private set;} public void Setup(ReflectableGameController owner,int row,int col,int hp,int max,ReflectableBlockType type){Row=row;Column=col;HP=hp;MaxHP=max;Type=type;Refresh();} public void ApplyDamage(int amount){HP-=amount;Refresh();StartCoroutine(Punch());} void Refresh(){if(hpLabel)hpLabel.text=HP.ToString();} IEnumerator Punch(){var s=transform.localScale;transform.localScale=s*1.12f;yield return new WaitForSeconds(.07f);if(this)transform.localScale=s;} public IEnumerator MoveTo(Vector2 target,float duration){var start=(Vector2)transform.position;for(float t=0;t<duration;t+=Time.deltaTime){transform.position=Vector2.Lerp(start,target,t/duration);yield return null;}if(this)transform.position=target;} } }
